class Priority(Enum):
    """
    Priority for the `PrioritizedIdentifier` class.

    `queue.PriorityQueue` has a lowest-value-is-highest-priority system, but
    setting `PrioritizedIdentifier.priority` to 0 can make it look as if priority is
    disabled. Using an `Enum` can help with that.
    """

    HIGH = 0
    LOW = 1

    def __lt__(self, other):
        if isinstance(other, Priority):
            return self.value < other.value
        return NotImplemented


@dataclass(eq=False, slots=True)
class PrioritizedIdentifier:
    """
    Represent an ISBN or ASIN in the Amazon lookup queue. The queue sorts by
    priority and then by submission time. Identity depends only on `identifier`,
    so repeated requests for the same product can be deduplicated.

    Therefore, priority 0, which is equivalent to `Priority.HIGH`, is the highest
    priority.

    `stage_import` controls whether the fetched product is staged for import;
    every fetched product is cached regardless of this setting.
    """

    identifier: str
    stage_import: bool = True
    priority: Priority = Priority.LOW
    timestamp: datetime = field(default_factory=datetime.now)

    def __eq__(self, other: object) -> bool:
        if isinstance(other, PrioritizedIdentifier):
            return self.identifier == other.identifier
        return NotImplemented

    def __hash__(self) -> int:
        return hash(self.identifier)

    def __lt__(self, other: object) -> bool:
        if isinstance(other, PrioritizedIdentifier):
            return (self.priority, self.timestamp) < (other.priority, other.timestamp)
        return NotImplemented

    def to_dict(self) -> dict[str, str | bool]:
        """Return all queue fields in JSON-compatible types."""
        return {
            "identifier": self.identifier,
            "stage_import": self.stage_import,
            "priority": self.priority.name,
            "timestamp": self.timestamp.isoformat(),
        }


class PrioritizedISBN(PrioritizedIdentifier):
    """Compatibility wrapper for callers using the old ISBN-specific interface."""

    __slots__ = ()

    def __init__(
        self,
        isbn: str,
        priority: Priority = Priority.LOW,
        timestamp: datetime | None = None,
        *,
        stage_import: bool = True,
    ):
        super().__init__(
            identifier=isbn,
            stage_import=stage_import,
            priority=priority,
            timestamp=timestamp if timestamp is not None else datetime.now(),
        )

    @property
    def isbn(self) -> str:
        return cache_key

    if (source_records := product.get("source_records")) and (
        amazon_record := next(
            (record for record in source_records if record.startswith("amazon:")), ""
        )
    ):
        return amazon_record.split(":")[1]

    return ""


def product_identifiers(product: dict) -> set[str]:
    """Return identifiers that can associate an Amazon product with its request."""
    identifiers = set(product.get('isbn_10') or [])
    identifiers.update(product.get('isbn_13') or [])
    identifiers.update(
        record.removeprefix('amazon:')
        for record in product.get('source_records') or []
        if record.startswith('amazon:')
    )
    return identifiers


def process_amazon_batch(identifiers: list[PrioritizedIdentifier | str]) -> None:
    """
    Fetch products and cache all of them. Only stage products requested for import.

    Plain string identifiers retain the original stage-for-import behavior.
    """
    requests = [
        item if isinstance(item, PrioritizedIdentifier) else PrioritizedIdentifier(item)
        for item in identifiers
    ]
    request_identifiers = [item.identifier for item in requests]
    logger.info(f"process_amazon_batch(): {len(request_identifiers)} items")
    try:
        products = web.amazon_api.get_products(request_identifiers, serialize=True)
        # stats_ol_affiliate_amazon_imports - Open Library - Dashboards - Grafana
        # http://graphite.us.archive.org Metrics.stats.ol...
        stats.increment(
            "ol.affiliate.amazon.total_items_fetched",
            n=len(products),
        )
    except Exception:
        logger.exception(
            f"amazon_api.get_products({request_identifiers}, serialize=True)"
        )
        return

    for product in products:
        cache_key = make_cache_key(product)  # isbn_13 or non-ISBN-10 ASIN.
        cache.memcache_cache.set(  # Add each product to memcache
            f'amazon_product_{cache_key}', product, expires=WEEK_SECS
        )

    # Only proceed if config finds infobase db creds
    if not config.infobase.get('db_parameters'):  # type: ignore[attr-defined]
        logger.debug("DB parameters missing from affiliate-server infobase")
        return

    staged_identifiers = {
        item.identifier for item in requests if item.stage_import
    }
    books = [
        clean_amazon_metadata_for_load(product)
        for product in products
        if staged_identifiers.intersection(product_identifiers(product))
    ]

    if books:
        stats.increment(
            "ol.affiliate.amazon.total_items_batched_for_import",
            n=len(books),
        )
        get_current_amazon_batch().add_items(
            [
                {'ia_id': b['source_records'][0], 'status': 'staged', 'data': b}
                for b in books
            ]
        )


