def amazon_lookup(site, stats_client, logger) -> None:
    """
    A separate thread of execution that uses the time up to API_MAX_WAIT_SECONDS to
    create a list of identifiers that is not larger than API_MAX_ITEMS_PER_CALL
    and then passes them to process_amazon_batch().
    """
    stats.client = stats_client
    web.ctx.site = site

    while True:
        start_time = time.time()
        items: dict[str, PrioritizedIdentifier] = {}  # no duplicates in the batch
        while len(items) < API_MAX_ITEMS_PER_CALL and seconds_remaining(
            start_time
        ):
            try:  # queue.get() will block (sleep) until successful or it times out
                item = web.amazon_queue.get(timeout=seconds_remaining(start_time))
                if existing := items.get(item.identifier):
                    existing.stage_import |= item.stage_import
                else:
                    items[item.identifier] = item
            except queue.Empty:
                pass
        logger.info(f"Before amazon_lookup(): {len(items)} items")
        if items:
            time.sleep(seconds_remaining(start_time))
            try:
                process_amazon_batch(list(items.values()))
                logger.info(f"After amazon_lookup(): {len(items)} items")
            except Exception:
                logger.exception("Amazon Lookup Thread died")
                stats_client.incr("ol.affiliate.amazon.lookup_thread_died")


