        daemon=True,
    )
    thread.start()
    return thread


def enqueue_identifier(item: PrioritizedIdentifier) -> None:
    """Queue a product once, promoting repeated requests when needed."""
    with submit_lock:
        with web.amazon_queue.mutex:
            for queued in web.amazon_queue.queue:
                if queued == item:
                    queued.stage_import |= item.stage_import
                    if item.priority < queued.priority:
                        queued.priority = item.priority
                        heapq.heapify(web.amazon_queue.queue)
                    return
        web.amazon_queue.put_nowait(item)


